# 只读分析：spawn_teammate / workflow 使用者 vs 未使用者的 token 效率对比
$d = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
$files = Get-ChildItem $d -Filter session-*.json
$fan = @(); $ser = @(); $orch = @()
foreach ($f in $files) {
  try { $o = Get-Content $f.FullName -Raw | ConvertFrom-Json } catch { continue }
  $rows = if ($o.record) { $o.record.rows } else { $o.rows }
  if (-not $rows) { continue }
  $tu = $rows.tokenUsage.val.totals
  if (-not $tu) { continue }
  $unc = [double]($tu.uncachedInputTokens); if (-not $unc) { $unc = 0 }
  $cr  = [double]($tu.cacheReadTokens);    if (-not $cr)  { $cr = 0 }
  $op  = [double]($tu.outputTokens);       if (-not $op)  { $op = 0 }
  if (($unc + $cr + $op) -eq 0) { continue }
  $st = $rows.sessionStats.val
  $steps = [double]($st.steps); if (-not $steps) { $steps = 0 }
  $nST = 0; $nWF = 0; $nOR = 0
  $ca = $rows.contextActivity.val
  if ($ca -and $ca.days) {
    foreach ($p in $ca.days.PSObject.Properties) {
      $dd = $p.Value
      if ($dd.tools) {
        if ($dd.tools.spawn_teammate) { $nST += $dd.tools.spawn_teammate.n }
        if ($dd.tools.workflow)       { $nWF += $dd.tools.workflow.n }
        if ($dd.tools.orchestrate)    { $nOR += $dd.tools.orchestrate.n }
      }
    }
  }
  $equiv = $cr * 0.1 + $unc + $op * 4
  $hit = 0; if (($cr + $unc) -gt 0) { $hit = $cr / ($cr + $unc) }
  $perStep = 0; if ($steps -gt 0) { $perStep = $unc / $steps }
  $eqStep = 0; if ($steps -gt 0) { $eqStep = $equiv / $steps }
  $rec = [pscustomobject]@{ equiv=$equiv; steps=$steps; perStep=$perStep; hit=$hit; eqStep=$eqStep; nST=$nST; nWF=$nWF; nOR=$nOR }
  if ($nST -gt 0 -or $nWF -gt 0) { $fan += $rec }
  elseif ($nOR -gt 0) { $orch += $rec }
  else { $ser += $rec }
}
function Stats($arr, $label) {
  if ($arr.Count -eq 0) { "{0}: 0 会话" -f $label; return }
  $eq = $arr | Sort-Object equiv | ForEach-Object { $_.equiv }
  $med = $eq[[int][Math]::Floor($eq.Count / 2)]
  $sumE = ($arr | Measure-Object equiv -Sum).Sum
  $mPer = ($arr | Measure-Object perStep -Average).Average
  $mHit = ($arr | Measure-Object hit -Average).Average
  $mStp = ($arr | Measure-Object steps -Average).Average
  $mEqS = ($arr | Measure-Object eqStep -Average).Average
  $p90 = $eq[[int][Math]::Floor($eq.Count * 0.9)]
  "{0}: n={1}  总等效={2}  等效中位={3}  P90={4}  均steps={5}  均uncached/step={6}  均等效/step={7}  均命中率={8}" -f `
    $label, $arr.Count, [Math]::Round($sumE/1e6,1)+'M', [Math]::Round($med/1e3,0)+'k', [Math]::Round($p90/1e3,0)+'k', `
    [Math]::Round($mStp,0), [Math]::Round($mPer/1e3,1)+'k', [Math]::Round($mEqS/1e3,1)+'k', [Math]::Round($mHit,3)
}
"数据目录: $d"
"会话文件: $($files.Count)"
"========== 分组对比 =========="
Stats $fan  "A组 用过spawn_teammate/workflow"
Stats $orch "B组 只用过orchestrate     "
Stats $ser  "C组 纯串行(三者都没用)    "
"========== A组明细 =========="
"spawn_teammate 调用总次数: $(($fan | Measure-Object nST -Sum).Sum)"
"workflow 调用总次数:       $(($fan | Measure-Object nWF -Sum).Sum)"
$top = $fan | Sort-Object equiv -Descending | Select-Object -First 5
foreach ($t in $top) { "  大会话: equiv=$([Math]::Round($t.equiv/1e6,2))M steps=$($t.steps) ST=$($t.nST) WF=$($t.nWF) OR=$($t.nOR)" }

